					if (iconLocalPath && !node_fs.existsSync(iconLocalPath)) iconLocalPath = void 0;
					if ((!iconLocalPath || !!iconLocalPath && !!iconDownloadedFrom && !!iconSource && iconDownloadedFrom !== iconSource) && iconSource && /^https?:\/\//i.test(iconSource) && !isWithinIconDownloadCooldown(iconDownloadFailedAt)) downloadSkillIconAndPersist(fetchFn, skillDir, metaPath, iconSource);
