		const dlResponse = await deps.fetchFn(downloadUrl, { headers });
		if (!dlResponse.ok) {
			console.error(`${TAG$20} [knotInstall] Failed to get download URL: ${dlResponse.status} ${dlResponse.statusText}`);
			return {
				success: false,
				skillName: skillIdentifier,
				errorMessage: `[DOWNLOAD_ERROR] ${dlResponse.status} ${dlResponse.statusText}`
			};
		}
		const dlBody = await dlResponse.json();
		if (dlBody.code !== 0 || !dlBody.data?.file_url) {
			console.error(`${TAG$20} [knotInstall] Download URL response error: code=${dlBody.code}, message=${dlBody.message}`);
			return {
				success: false,
				skillName: skillIdentifier,
				errorMessage: `[DOWNLOAD_ERROR] ${dlBody.message ?? "missing file_url"}`
			};
		}
		let zipUrl = dlBody.data.file_url;
