		if (validIconUrl) metaPayload.iconSource = validIconUrl;
		if (reusedIconLocalPath) {
			metaPayload.iconLocalPath = reusedIconLocalPath;
			if (reusedIconDownloadedFrom) metaPayload.iconDownloadedFrom = reusedIconDownloadedFrom;
		}
		node_fs.writeFileSync(metaPath, JSON.stringify(metaPayload, null, 2));
