	/** 每次请求前 await 一次 getApiKey()，捕获运行时配置变更；失败时返回 undefined 不带头。 */
	async function resolveApiKey() {
		if (!getApiKey) return;
		try {
			return await getApiKey();
		} catch (err) {
			console.warn(`${TAG$20} [SkillHub] getApiKey failed; sending request without X-API-Key:`, String(err));
			return;
		}
	}
