			if (bareSlugs.length > 0) body.slugs = bareSlugs;
			if (coordinates.length > 0) body.coordinates = coordinates;
			const response = await skillHubFetch(`${SKILLHUB_BASE_URL}/api/v1/skills/exists`, {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify(body)
			});
			if (!response.ok) return {
				exists: {},
				count: 0
			};
