/**
* 识别 Ardot 设计稿分享 / 打开用的 https file URL。
*
* 形如：
* - https://ardot.tencent.com/file/<id>
* - https://test.ardot.tencent.com/file/<id>?from=workbuddy
*
* 这类 URL 对应已由 MCP App Host（create_design / open_design）展示的画布；
* 不应再经 present_files → openBrowser 用内置浏览器打开（会丢 ui-bridge）。
*/
var ARDOT_FILE_PATH = /^\/file\/[^/]+\/?$/i;
function isArdotHostname(hostname) {
	const host = hostname.toLowerCase();
	return host === "ardot.tencent.com" || host.endsWith(".ardot.tencent.com");
}
/**
* 是否为 Ardot Web origin / URL（含 embed、file 等任意路径）。
*
* 用于 Electron 主进程剪贴板权限白名单：Ardot iframe（如
* `https://ardot.tencent.com/embed?...`）内调用 navigator.clipboard.writeText
* 时，session permission handler 必须以该 origin 放行，否则表现为
* `NotAllowedError: Write permission denied`。
*/
function isArdotWebOriginUrl(originOrUrl) {
	if (typeof originOrUrl !== "string" || !originOrUrl.trim()) return false;
	try {
		const url = new URL(originOrUrl.trim());
		if (url.protocol !== "http:" && url.protocol !== "https:") return false;
		return isArdotHostname(url.hostname);
	} catch {
		return false;
	}
}
/**
* 是否为 Ardot 设计稿 file URL（仅 http(s) + ardot 域 + /file/<id>）。
*/
function isArdotDesignFileUrl(raw) {
	if (typeof raw !== "string" || !raw.trim()) return false;
	try {
		const url = new URL(raw.trim());
		if (url.protocol !== "http:" && url.protocol !== "https:") return false;
		if (!isArdotHostname(url.hostname)) return false;
		return ARDOT_FILE_PATH.test(url.pathname);
	} catch {
		return false;
	}
}
