//#region ../../packages/workbuddy-server/src/mcp/builtin-tools/tools/preview-resolver.ts
/**
* Preview Target Resolver
*
* 从原 preview-url-tool.ts 抽取的「可预览目标」解析逻辑，供 present_files 工具复用。
*
* 职责：把一个原始输入（绝对路径 / file:// URI / http(s) URL）解析成可在桌面内置
* 浏览器面板打开的最终 URL，并对远程 / localhost URL 做：
*   - 协议白名单校验（只接受 http/https/file/绝对路径，拦截 javascript:/data: 等绕过）
*   - URL 黑名单校验（读 ProductManager 配置的 blacklistURLs/blacklistDomains）
*   - localhost/127.0.0.1 可达性探测（不可达时返回引导文案，提示先用 Bash 起 server）
*
* 本地文件支持：
* - file:// URI 直接传递
* - 绝对路径自动转换为 file:// URI
* - webview partition 已注册 file 协议 handler（见 WindowManager.registerLocalFileProtocol）
*/
var LOG_KEY = "[preview-resolver]";
/**
* 单次探测 localhost URL 是否可达（HEAD 请求，2s 超时）
*/
function probeOnce(url) {
	return new Promise((resolve) => {
		try {
			const req = (new URL(url).protocol === "https:" ? node_https : node_http).request(url, {
				method: "HEAD",
				timeout: 2e3
			}, (res) => {
				res.resume();
				resolve(true);
			});
			req.on("error", () => resolve(false));
			req.on("timeout", () => {
				req.destroy();
				resolve(false);
			});
			req.end();
		} catch {
			resolve(false);
		}
	});
}
function sleep(ms) {
	return new Promise((resolve) => setTimeout(resolve, ms));
}
/**
* 带重试的 localhost 可达性探测
* 最多尝试 maxRetries+1 次，每次间隔 retryDelayMs
* 用于应对 LLM 刚用 Bash 起了 server 但还没就绪的情况
*/
async function isLocalhostReachable(url, maxRetries = 2, retryDelayMs = 1500) {
	for (let attempt = 0; attempt <= maxRetries; attempt++) {
		if (await probeOnce(url)) return true;
		if (attempt < maxRetries) {
			console.log(`${LOG_KEY} localhost probe attempt ${attempt + 1} failed, retrying in ${retryDelayMs}ms...`);
			await sleep(retryDelayMs);
		}
	}
	return false;
}
/**
* 尝试从 localhost URL 的 pathname 推断本地文件路径
* 例如 http://localhost:8080/cosmos.html + cwd=/Users/foo/bar → /Users/foo/bar/cosmos.html
*/
function tryResolveLocalFile(url, cwd) {
	try {
		const parsed = new URL(url);
		const pathname = decodeURIComponent(parsed.pathname);
		if (!pathname || pathname === "/") return;
		const relativePath = pathname.startsWith("/") ? pathname.slice(1) : pathname;
		if (!relativePath) return;
		if (cwd) {
			const fullPath = node_path.join(cwd, relativePath);
			try {
				if ((0, node_fs.existsSync)(fullPath)) return fullPath;
			} catch {}
		}
		return;
	} catch {
		return;
	}
}
/**
* URL 黑名单检查（与原版 UrlContentFetcher.isBlacklist 逻辑一致）
*/
async function isBlacklist(url, productManager) {
	try {
		const configuration = await Promise.race([productManager.waitConfiguration(), new Promise((resolve) => setTimeout(() => resolve(void 0), 3e3))]);
		if (!configuration) {
			console.warn(`${LOG_KEY} Blacklist check skipped: configuration not available within 3s timeout`);
			return false;
		}
		const blacklistURLs = (configuration?.config)?.blacklistURLs;
		const blacklistDomains = (configuration?.config)?.blacklistDomains;
		const normalizedUrl = url.trim();
		const hostname = new URL(normalizedUrl).hostname.toLowerCase();
		const isUrlBlocked = Array.isArray(blacklistURLs) && blacklistURLs.some((item) => typeof item === "string" && item.trim().toLowerCase() === normalizedUrl.toLowerCase());
		const isDomainBlocked = Array.isArray(blacklistDomains) && blacklistDomains.some((domain) => {
			if (typeof domain !== "string") return false;
			const targetDomain = domain.trim().toLowerCase();
			return targetDomain && hostname === targetDomain;
		});
		return isUrlBlocked || isDomainBlocked;
	} catch (error) {
		console.warn(`${LOG_KEY} Blacklist check failed, allowing URL:`, error);
		return false;
	}
}
/**
* 把一个原始输入解析为可预览 URL。
*
* - 绝对路径 → file:// URI（有 HTTP server 时 HTML 文件走 HTTP URL 避免 CORS）
* - file:// URI → 原样
* - http/https URL → 协议二次校验 + 黑名单 + localhost 可达性探测
*
* 校验失败返回 { ok: false, errorText }，由调用方决定是整体失败还是跳过该项。
*/
async function resolvePreviewTarget(rawUrl, cwd, productManager, staticHtmlServer) {
	const url = rawUrl;
	if (!url) return {
		ok: false,
		errorText: "Error: url is required"
	};
	const isAbsolutePath = node_path.isAbsolute(url);
	const isFileUri = url.startsWith("file://");
	const isHttpUri = /^https?:\/\//i.test(url);
	if (!isAbsolutePath && !isFileUri && !isHttpUri) return {
		ok: false,
		errorText: `Error: Unsupported URL. Only http/https URLs, file:// URIs, and absolute file paths are accepted. Got: ${url}`
	};
	if (isAbsolutePath) {
		if (staticHtmlServer && /\.(html?|htm)$/i.test(node_path.extname(url))) {
			const port = staticHtmlServer.getServerPort();
			if (port > 0) {
				const dirPath = node_path.dirname(url);
				const basename = node_path.basename(url);
				return {
					ok: true,
					previewUrl: `http://127.0.0.1:${port}/static-html/${staticHtmlServer.registerDir(dirPath)}/${encodeURIComponent(basename)}`
				};
			}
		}
		return {
			ok: true,
			previewUrl: `file://${url}`
		};
	}
	if (isFileUri) {
		if (staticHtmlServer) try {
			const localPath = (0, node_url.fileURLToPath)(url);
			if (/\.html?$/i.test(node_path.extname(localPath))) {
				const port = staticHtmlServer.getServerPort();
				if (port > 0) {
					const suffixMatch = /[?#]/.exec(url);
					const suffix = suffixMatch ? url.slice(suffixMatch.index) : "";
					const dirPath = node_path.dirname(localPath);
					const basename = node_path.basename(localPath);
					return {
						ok: true,
						previewUrl: `http://127.0.0.1:${port}/static-html/${staticHtmlServer.registerDir(dirPath)}/${encodeURIComponent(basename)}${suffix}`
					};
				}
			}
		} catch {}
		return {
			ok: true,
			previewUrl: url
		};
	}
	let parsedUrl;
	try {
		parsedUrl = new URL(url);
	} catch {
		return {
			ok: false,
			errorText: `Error: Invalid URL format: ${url}`
		};
	}
	if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") return {
		ok: false,
		errorText: `Error: Unsupported protocol: ${parsedUrl.protocol}. Accepted: http/https URLs or local file paths.`
	};
	if (await isBlacklist(url, productManager)) return {
		ok: false,
		errorText: `Error: IMPORTANT: Current URL is high risk! This ${url} is blocked!`
	};
	const hostname = parsedUrl.hostname.toLowerCase();
	if (hostname === "localhost" || hostname === "127.0.0.1") {
		if (!await isLocalhostReachable(url)) {
			const port = parsedUrl.port || (parsedUrl.protocol === "https:" ? "443" : "80");
			const pathname = decodeURIComponent(parsedUrl.pathname);
			const localFile = tryResolveLocalFile(url, cwd);
			const lines = [
				`Error: ${url} is not reachable — no server is running on port ${port}.`,
				"",
				"To preview this URL, you need to start a local server first using the Bash tool.",
				"",
				"Suggested actions:"
			];
			if (localFile) lines.push(`  1. The file exists at: ${localFile}`, "  2. Start a server in that directory, for example:", `     cd ${cwd} && python3 -m http.server ${port}`, `     or: cd ${cwd} && npx serve -l ${port}`, `  3. Then call present_files again with ${url}`, "", `  Alternatively, if the file is a simple static HTML with no JS fetch/routing, you can pass the absolute file path directly: ${localFile}`);
			else if (cwd) lines.push(`  1. No file matching pathname "${pathname}" found in ${cwd}`, "  2. Start a server in your working directory:", `     cd ${cwd} && python3 -m http.server ${port}`, `     or: cd ${cwd} && npx serve -l ${port}`, "  3. Then call present_files again with the correct URL");
			else lines.push("  1. Start a local server using the Bash tool (e.g., python3 -m http.server or npx serve)", `  2. Make sure it listens on port ${port}`, "  3. Then call present_files again with the server URL");
			return {
				ok: false,
				errorText: lines.join("\n")
			};
		}
	}
	return {
		ok: true,
		previewUrl: url
	};
}
